class HfMarginOrder(TypedDict):
  """A single margin high-frequency (hf) order row, as returned by Get Order By OrderId/ClientOid and as an item of Get Open Orders and Get Closed Orders."""

  id: str
  """System-generated order id."""
  symbol: str
  """Trading pair symbol."""
  opType: Literal['DEAL', 'CANCEL']
  """Operation type."""
  type: Literal['limit', 'market']
  """Order type."""
  side: Literal['buy', 'sell']
  """Order side."""
  price: str
  """Order price."""
  size: str
  """Order quantity, in the trading pair's base currency."""
  funds: str
  """Order value, in the trading pair's quote currency."""
  dealSize: str
  """Quantity that has been filled."""
  dealFunds: str
  """Value of the filled portion."""
  fee: str
  """Trading fee charged so far."""
  feeCurrency: str
  """Currency the trading fee is charged in."""
  stp: Literal['CN', 'CO', 'CB', 'DC'] | None
  """Self-trade prevention strategy, or `null` when none was requested."""
  stop: str | None
  """Stop-order type this order originated from, or `null` when it did not."""
  stopTriggered: bool
  """Whether the originating stop condition has triggered."""
  stopPrice: str
  """Stop trigger price, for an order that originated from a stop order."""
  timeInForce: Literal['GTC', 'GTT', 'IOC', 'FOK']
  """Order timing strategy."""
  postOnly: bool
  """Whether the order was placed as post-only (maker-only)."""
  hidden: bool
  """Whether the order is a hidden order. Hidden-order placement (the `hidden` request parameter) was discontinued 2026-08-03; this response field remains and reads `false` for every order placed since."""
  iceberg: bool
  """Whether the order is an iceberg order. Iceberg-order placement (the `iceberg` request parameter) was discontinued 2026-08-03; this response field remains and reads `false` for every order placed since."""
  visibleSize: str
  """Visible quantity for an iceberg order. Iceberg placement was discontinued 2026-08-03; this response field remains and reads `"0"` for every order placed since."""
  cancelAfter: int
  """Seconds after which the order auto-cancels, for `timeInForce: GTT`; `0` otherwise."""
  channel: str
  """Where the order was placed from, e.g. `API` or `WEB`. KuCoin does not publish the closed set of values, so this is left as a plain string rather than a guessed enum."""
  clientOid: str | None
  """Client-provided order id, or `null` for an order placed without one (e.g. from the KuCoin web/app UI)."""
  remark: str | None
  """Remarks supplied at order placement, or `null` when none was given."""
  tags: str | None
  """Order tag supplied at placement, or `null` when none was given."""
  cancelExist: bool
  """Whether the order has ever had a cancellation request applied to it (partially or fully)."""
  createdAt: TimestampMillis
  """Order creation time."""
  lastUpdatedAt: TimestampMillis
  """Time the order was last updated."""
  tradeType: str
  """Margin trade classification. KuCoin's examples show `MARGIN_TRADE` (cross) and `MARGIN_ISOLATED_TRADE` (isolated) -- both confirmed as accepted request values live 2026-08-08 -- but this exact endpoint's docs page never states the field is a closed set, so it is left as a plain string rather than a guessed enum."""
  inOrderBook: bool
  """Whether the order is currently resting in the order book."""
  cancelledSize: str
  """Quantity cancelled so far."""
  cancelledFunds: str
  """Value of the cancelled portion."""
  remainSize: str
  """Quantity not yet filled or cancelled."""
  remainFunds: str
  """Value of the portion not yet filled or cancelled."""
  tax: str
  """Tax amount charged against this order."""
  cancelReason: int | None
  """Numeric cancellation reason code, or `null` while the order has never been cancelled. KuCoin does not publish the code table, so this is left as a plain integer rather than a guessed enum."""
  active: bool
  """Whether the order is still active (not fully filled or cancelled)."""


