class PositionDetail(TypedDict):
  """A futures position's full detail: PnL, margin and liquidation figures for one contract symbol. Shared by Get Position Details (one symbol) and Get Position List (an array of these, one per symbol with a nonzero/open position or a persisted margin-mode setting). Always returned even for a symbol with no open position -- most numeric fields are simply zeroed in that case, confirmed live."""

  id: str
  """Position ID."""
  symbol: str
  """Symbol of the contract."""
  crossMode: bool
  """Whether this is a cross-margin position."""
  delevPercentage: float
  """ADL (auto-deleveraging) ranking percentile."""
  openingTimestamp: int
  """First opening time, Unix milliseconds."""
  currentTimestamp: int
  """Current server timestamp, Unix milliseconds."""
  currentQty: int
  """Current position quantity."""
  currentCost: float
  """Current position value."""
  currentComm: float
  """Current commission."""
  unrealisedCost: float
  """Unrealised value."""
  realisedGrossCost: float
  """Accumulated realised gross profit value."""
  realisedCost: float
  """Current realised position value."""
  isOpen: bool
  """Whether the position is currently open."""
  markPrice: float
  """Mark price."""
  markValue: float
  """Value at mark price."""
  posCost: float
  """Position value."""
  posInit: float
  """Initial margin. Cross = opening value / cross leverage; isolated = accumulation of initial margin for each transaction."""
  posMargin: float
  """Bankruptcy cost. Cross = mark value * IMR; isolated = position margin (accumulation of initial margin, additional margin, generated funding fees, etc.)."""
  realisedGrossPnl: float
  """Accumulated realised gross profit value."""
  realisedPnl: float
  """Realised profit and loss."""
  unrealisedPnl: float
  """Unrealised profit and loss."""
  unrealisedPnlPcnt: float
  """Profit-loss ratio of the position."""
  unrealisedRoePcnt: float
  """Rate of return on investment."""
  avgEntryPrice: float
  """Average entry price."""
  liquidationPrice: float
  """Liquidation price. For cross margin, liquidation is based on the account's risk rate rather than this figure alone."""
  bankruptPrice: float
  """Bankruptcy price. For cross margin, liquidation is based on the account's risk rate rather than this figure alone."""
  settleCurrency: str
  """Currency used to clear and settle the trades."""
  isInverse: bool
  """Whether this is an inverse (coin-margined) contract."""
  marginMode: Literal['CROSS', 'ISOLATED']
  """Margin mode: `CROSS` or `ISOLATED`."""
  positionSide: Literal['BOTH']
  """Position side. `BOTH` means one-way position mode (the only mode KuCoin Futures currently documents)."""
  leverage: float
  """Leverage."""
  autoDeposit: NotRequired[bool]
  """Whether margin is automatically deposited to avoid liquidation. Only applicable to isolated margin."""
  maintMarginReq: NotRequired[float]
  """Maintenance margin requirement. Only applicable to isolated margin."""
  riskLimit: NotRequired[int]
  """Risk limit. Only applicable to isolated margin."""
  realLeverage: NotRequired[float]
  """Leverage actually in effect for the position. Only applicable to isolated margin."""
  posCross: NotRequired[float]
  """Added margin. Only applicable to isolated margin."""
  posCrossMargin: NotRequired[int]
  """Additional margin calls (automatic, manual, adjusted risk limits). Only applicable to isolated margin."""
  posComm: NotRequired[float]
  """Bankruptcy cost. Only applicable to isolated margin."""
  posCommCommon: NotRequired[float]
  """Part of bankruptcy cost (positioning, add margin). Only applicable to isolated margin."""
  posLoss: NotRequired[float]
  """Funding fees paid out. Only applicable to isolated margin."""
  posFunding: NotRequired[float]
  """Current remaining unsettled funding fee for the position. Only applicable to isolated margin."""
  posMaint: NotRequired[float]
  """Maintenance margin."""
  maintMargin: NotRequired[float]
  """Position margin. Only applicable to isolated margin."""
  maintainMargin: NotRequired[float]
  """Maintenance margin rate. Only applicable to isolated margin."""
  riskLimitLevel: NotRequired[int]
  """Risk limit level currently in effect for the symbol. Not documented in the venue's OpenAPI spec; observed live on Get Position Details."""
  withdrawPnl: NotRequired[float]
  """Realised profit already withdrawn from the position. Not documented on this endpoint's own OpenAPI spec (though the equivalent field is documented on Get Positions History); observed live on Get Position Details."""
  aggRate: NotRequired[float]
  """Aggregate funding rate applied to the position. Not documented in the venue's OpenAPI spec; observed live on Get Position Details."""


class TradeWsCancelOrderArgs(TypedDict):
  """Business parameters (the `args` field) of a Pro WebSocket Cancel Order command, shared by the `spot.cancel`, `spot.sync_cancel` and `futures.cancel` operations (`wss://wsapi.kucoin.com/v1/private`). `margin.cancel` takes the identical shape but is out of scope for this pass; `uta.cancel` additionally takes `tradeType` and is out of scope entirely (UTA). Mirrors whichever REST cancel-by-orderId/cancel-by-clientOid endpoint the selected `op` corresponds to."""

  symbol: str
  """Trading pair (Spot) or contract (Futures) symbol the order belongs to. The venue's own docs mark this optional at the WS-command level ('required only when the RESTful Endpoint corresponding to the selected op requires symbol'), but every REST cancel endpoint this command can dispatch to -- Spot and Futures Cancel by OrderId, Cancel by ClientOid -- requires it as a query parameter, so it is required here too."""
  orderId: NotRequired[str]
  """System-generated id of the order to cancel. Choose exactly one of `orderId`/`clientOid`; per the venue's docs, if both are given only `clientOid` takes effect."""
  clientOid: NotRequired[str]
  """Client-provided id of the order to cancel. Choose exactly one of `orderId`/`clientOid`; per the venue's docs, if both are given only `clientOid` takes effect."""


WsSubscriptionAck = Literal['ack']


